const input = $input.first().json;
const start = $('Normalize Start Request').first().json;
const originalQuery = start.query ?? start.task ?? start.original_query ?? input.query ?? '';

let content = input.message?.content ?? input.content ?? input.response ?? input.output ?? '';
if (typeof content !== 'string') content = JSON.stringify(content);
content = String(content).trim();

let parsed = null;

if (content) {
  const cleaned = content
    .replace(/^\uFEFF/, '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace > firstBrace) {
    let jsonText = cleaned.slice(firstBrace, lastBrace + 1);
    try {
      parsed = JSON.parse(jsonText);
    } catch (error) {
      try {
        jsonText = jsonText.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');
        parsed = JSON.parse(jsonText);
      } catch (error2) {
        parsed = null;
      }
    }
  }
}

// Soft-fail: unusable LLM output -> fall back to the raw user query as the search query.
if (!parsed || typeof parsed !== 'object' || typeof parsed.query !== 'string' || !parsed.query.trim()) {
  parsed = { query: String(originalQuery || '').trim(), filters: {} };
}

if (!String(originalQuery || '').trim()) {
  throw new Error('MOMI Experience Query Parser: original user query is missing.');
}

return [{
  json: {
    ...start,
    original_query: String(originalQuery).trim(),
    experience_search_query: parsed.query.trim(),
    experience_filters: parsed.filters && typeof parsed.filters === 'object' ? parsed.filters : {},
    task_type: parsed.filters?.task_type ?? null,
    route: start.route ?? 'ACTION',
    requires_planner: Boolean(start.requires_planner ?? true),
    requires_tool: Boolean(start.requires_tool ?? true),
    session_id: start.session_id ?? 'new_session'
  }
}];

