const env = $json;
const steps = env.plan?.steps;

if (!Array.isArray(steps)) {
  throw new Error('MOMI: steps array is missing');
}

/*MOMI-PATCH:P3a.0*/const completedIds = new Set(
  steps.filter(step => step.completed === true).map(step => String(step.id))
);

// An optional step (e.g. the Pelicargo lookup that only feeds "DO Ref No.") must
// never block the run: once it has exhausted its retries, treat it as satisfied
// so downstream steps (EFC Domestic Billing) can still execute.
const skippedOptionalIds = new Set(
  steps
    .filter(step => step.failed === true && step.optional === true)
    .map(step => String(step.id))
);
const satisfiedIds = new Set([...completedIds, ...skippedOptionalIds]);

const nextStep = steps.find(step => {
  if (step.completed === true) return false;
  if (step.failed === true) return false;
  const dependencies = Array.isArray(step.depends_on) ? step.depends_on : [];
  return dependencies.every(dep => satisfiedIds.has(String(dep)));
});

const allCompleted = steps.length > 0 && steps.every(step => step.completed === true || skippedOptionalIds.has(String(step.id)));

let execution_status = 'ready';
let forceTerminal = false;
let termReason = null;
let current_step = null;
let next_step = null;
let all_steps_completed = false;

if (allCompleted) {
  execution_status = 'completed';
  all_steps_completed = true;
} else if (!nextStep) {
  const failedStep = steps.find(step => step.failed === true && step.optional !== true);
  if (failedStep) {
    execution_status = 'failed';
    current_step = failedStep.id;
  } else {
    const blockedNow = steps.filter(s => s.completed !== true && (Array.isArray(s.depends_on) ? s.depends_on : []).some(d => !satisfiedIds.has(String(d))));
    // Terminal, not a throw: a recovery already produced this shape once — rolling the
    // replan dice again cannot fix a malformed plan. Route to the terminal report.
    forceTerminal = true;
    if (blockedNow.length) {
      const hangIds = blockedNow.map(s => s.id).join(', ');
      const missingDeps = [...new Set(blockedNow.flatMap(s => (Array.isArray(s.depends_on) ? s.depends_on : []).map(String).filter(d => !completedIds.has(d))))].join(', ');
      termReason = `Plan has steps with unmet dependencies (${hangIds} need: ${missingDeps}). The (re)plan is malformed — fix the request or plan and re-run.`;
      execution_status = 'failed';
      current_step = blockedNow[0].id;
    } else {
      forceTerminal = true;
      termReason = 'MOMI: No ready step found. Check step dependencies for a cycle.';
      execution_status = 'failed';
    }
  }
} else {
  execution_status = 'ready';
  current_step = nextStep.id;
  next_step = nextStep;
}

const out = {
    ...env,
    plan: { ...env.plan, steps },
    state: {
      ...(env.state || {}),
      execution_status,
      current_step,
      next_step,
      all_steps_completed,
      needs_replan: execution_status === 'failed' ? (forceTerminal ? false : (env.state?.needs_replan !== false)) : false,
      status: execution_status,
      failure_reason: forceTerminal ? termReason : (env.state?.failure_reason ?? null),
      skipped_optional_steps: [...skippedOptionalIds]
    }
  };
  stashEnvelope(out);
  return [{ json: out }];

