function familyOf(name) {
  const n = String(name || '');
  if (/^clickup_/.test(n)) return 'clickup';
  if (/^efc_/.test(n)) return 'efc';
  if (/^credential_/.test(n)) return 'credential';
  if (/^pelicargo_/.test(n)) return 'web';
  if (/^(email_|calendar_)/.test(n)) return 'email';
  if (/^crm_/.test(n)) return 'clickup';
  if (/^(web_search|browser_)/.test(n)) return 'web';
  if (/^(qdrant_memory_|qdrant_experience_)/.test(n)) return 'memory';
  if (/^qdrant_document_/.test(n)) return 'documents';
  if (/^(pdf_|excel_|powerpoint_|report_|image_|file_write)/.test(n)) return 'artifact';
