// longest labels first so "freight" never swallows "inland freight".
const LINE_CATALOG=[
  {code:'3201',description:'Inland Freight'},
  {code:'3101',description:'Freight'},
  {code:'3064',description:'Profit Share'}
];
function linesFromQuery(text){
  let low=String(text||'').toLowerCase();
  const hits=[];
  const ordered=[...LINE_CATALOG].sort((a,b)=>b.description.length-a.description.length);
  for(const L of ordered){
    const needle=L.description.toLowerCase();
    const i=low.indexOf(needle);
    if(i>=0){
      hits.push({L,i});
      low=low.slice(0,i)+' '.repeat(needle.length)+low.slice(i+needle.length);
    }
  }
  return hits.sort((a,b)=>a.i-b.i).map(h=>({code:h.L.code,description:h.L.description,charge_amount:null,cost_amount:null,ap:true}));
}
