const url=q.match(/https?:\/\/[^\s<>"']+/i);
let pb=null;
const efc=/\b(eawb|fwb|fhl|efc|eftcloud|etransmission|etransmit|transmission status|transmitted)\b/i.test(s)&&
  (/\b\d{3}\s*[- ]?\s*\d{8}\b/.test(q)||/check|status|transmitted|sent|accepted/i.test(s));
if(efc)pb='efc_eawb_check';
else if(url&&/(scrape|directory|agents|contacts|introduc|excel|spreadsheet|xlsx|email)/.test(s))pb='scrape_and_draft';
else if(/(late|delay|miss|rollover)/.test(s)&&/(appt|appointment|customer|sop|notify|follow)/.test(s))pb='delay_follow_sop';
else if(/\bpod\b/.test(s)&&/(request|send|email|mail)/.test(s))pb='pod_request';
else if(/(report|recap|excel|spreadsheet)/.test(s)&&/(delay|load|shipment)/.test(s))pb='delay_report';
else if(/(clickup|task)/.test(s)&&/(create|open|add|update)/.test(s))pb='clickup_task';

if(!pb)return[{json:{...$json,playbook:null,use_llm_planner:true}}];

let goal=q,steps=[];
if(pb==='efc_eawb_check'){
  const m=(q.match(/\b\d{3}\s*[- ]?\s*\d{8}\b/)||[])[0]||null;
  goal=`Check eAWB transmission status — MAWB ${m||'(from query)'}`;
  steps=[
    st('step_1','credential_lookup','credential','Retrieve EFC credentials',{
      service:'efc',lookup_fields:['efc_username','efc_password','efc_base_url','efc_username_selector','efc_password_selector','efc_login_button_selector']
    }),
    st('step_2','efc_browser','efc','Login to EFC and inspect eAWB/FWB',{
      operation:'FULL_CHECK',session_id:`efc-${$json.session_id||'default'}`,operations:'FULL_CHECK',
      mawb:m,credentials_from_step:'step_1',timeout:180000,screenshot:true
    },['step_1'])
  ];
}
return[{json:{...$json,playbook:pb,use_llm_planner:false,plan:{goal,steps},validated:true}}];

